{"command":["bash","-lc","python - <<'PY'
import json, glob, os
alerts=[]
for f in sorted(glob.glob('alerts/alerts_at_*.json')):
    data=json.load(open(f))
    if isinstance(data, dict) and 'alerts' in data:
        items=data['alerts']
    else:
        items=data
    for a in items:
        if a.get('labels',{}).get('namespace')=='otel-demo':
            alerts.append(a)
# group by alertname
from collections import defaultdict
byname=defaultdict(list)
for a in alerts:
    name=a['labels'].get('alertname')
    byname[name].append(a)
for name,items in byname.items():
    print('Alert:',name,'count',len(items))
    services=sorted({it['labels'].get('service_name') for it in items if it['labels'].get('service_name')})
    print(' services',services)
PY"],"workdir":"/root/projects/open_source/zero/B96DF826-4BB2-4B62-97AB-6D84254C53D7/Scenario-6"}

